{
  "items": [
    {
      "title": "ACLED – Political Violence, Protests and Conflict Events in Germany (2020s)",
      "url_or_doi": "https://acleddata.com/country/germany",
      "justification": "The Armed Conflict Location & Event Data Project (ACLED) provides georeferenced event-level data on political violence, demonstrations, riots, and other disorder in Germany. Records include event dates, locations, actors, event types, and reported fatalities. Coverage includes the 2020s, making this dataset particularly useful for analyzing political conflict, protest movements, extremist violence, and domestic security trends."
    },
    {
      "title": "ACLED – Conflict and Protest Event Data Download",
      "url_or_doi": "https://acleddata.com/conflict-data/download-data",
      "justification": "Provides downloadable conflict and protest event data that can be filtered for Germany and the period 2020 onward. Researchers can investigate the geographic distribution, frequency, and characteristics of political violence and demonstrations. Particularly useful for spatial analysis, time-series research, and comparisons between German regions."
    },
    {
      "title": "German Federal Criminal Police Office – Police Crime Statistics (Polizeiliche Kriminalstatistik)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/24911/details",
      "justification": "Official German police crime statistics covering reported criminal offenses and suspects. The dataset includes annual observations during the 2020s and supports research into domestic security, crime trends, and public safety. It is particularly relevant for examining changes in recorded crime across Germany, although police-recorded offenses do not capture all criminal activity."
    },
    {
      "title": "BKA – Politically Motivated Crime in Germany (Politisch motivierte Kriminalität), 2024",
      "url_or_doi": "https://www.bka.de/SharedDocs/Downloads/DE/UnsereAufgaben/Deliktsbereiche/PMK/2024PMKFallzahlen.pdf?__blob=publicationFile&v=2",
      "justification": "Official statistics from Germany's Federal Criminal Police Office documenting politically motivated criminal offenses. The dataset includes classifications related to right-wing, left-wing, religiously motivated, and foreign-ideology-related offenses. It also provides historical comparisons covering years in the 2020s. Particularly valuable for studying political extremism, hate crimes, election-related violence, and threats to democratic institutions."
    },
    {
      "title": "OSCE ODIHR – Hate Crime Statistics for Germany (2020–2025)",
      "url_or_doi": "https://hatecrime.osce.org/germany",
      "justification": "The Organization for Security and Co-operation in Europe's Office for Democratic Institutions and Human Rights maintains annual hate crime statistics for Germany. Data include police-recorded hate crimes and classifications by bias motivation and offense type. The 2020s observations support research on antisemitism, racism, xenophobia, religious intolerance, anti-LGBTI violence, and social conflict. Official figures can be downloaded for further analysis."
    },
    {
      "title": "OSCE ODIHR – Detailed Hate Crime Incidents in Germany (2024)",
      "url_or_doi": "https://hatecrime.osce.org/incidents?country=DE&year=2024",
      "justification": "Provides detailed descriptions of hate crime incidents reported by civil society organizations and other contributors. Records can be filtered by country, year, incident category, and bias motivation. The dataset is useful for studying patterns of discrimination, extremist violence, attacks against minorities, and social tensions in Germany. These incident reports are not comprehensive and should not be interpreted as a complete count of hate crimes."
    },
    {
      "title": "German Federal Statistical Office – Criminal Convictions by Type of Offense, Age, Sex and Nationality",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/24311/table/24311-0002",
      "justification": "Official judicial statistics from Destatis covering criminal convictions in Germany, with observations available for 2020–2024. Includes offenses such as homicide, assault, robbery, and crimes against public order. Data can be disaggregated by age, sex, and nationality. Useful for studying criminal justice outcomes, public security, and changes in violent crime convictions during the 2020s."
    },
    {
      "title": "German Federal Statistical Office – Public Prosecution and Criminal Investigations (2018–2024)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/24211/table/24211-0001",
      "justification": "Official statistics on criminal investigations completed by German public prosecution authorities. The dataset includes annual figures for 2020–2024 and categories such as politically motivated offenses, state security offenses, homicide, violent assault, corruption, and other crimes. Particularly useful for examining how Germany's justice system responds to political conflict, public security threats, and serious criminal activity."
    },
    {
      "title": "BKA – Security and Crime in Germany Survey (Sicherheit und Kriminalität in Deutschland, SKiD)",
      "url_or_doi": "https://skid.bka.de/",
      "justification": "A nationwide victimization and security survey conducted by the German Federal Criminal Police Office in cooperation with state police authorities. Survey waves include 2020 and 2024. It provides information about experiences of crime, perceptions of safety, and victimization that may not appear in official police statistics. Particularly relevant for studying public perceptions of security, fear of crime, and the relationship between actual victimization and perceived threats."
    },
    {
      "title": "Global Peace Index – Germany Peace and Security Indicators",
      "url_or_doi": "https://www.visionofhumanity.org/maps/",
      "justification": "The Institute for Economics and Peace publishes the Global Peace Index, providing internationally comparable indicators of peacefulness. Downloadable historical data allow Germany's performance during the 2020s to be examined in relation to societal safety and security, ongoing conflict, and militarization. Suitable for comparative research examining Germany's peace and security conditions against other European countries."
    },
    {
      "title": "Uppsala Conflict Data Program – Armed Conflict and Organized Violence Datasets",
      "url_or_doi": "https://ucdp.uu.se/downloads/",
      "justification": "The Uppsala Conflict Data Program provides standardized datasets on armed conflicts, organized violence, conflict actors, and conflict-related fatalities. Its datasets include observations from the 2020s and can support research involving Germany's participation in international conflicts or comparisons with other countries. Germany is not necessarily represented as a conflict location in every dataset because UCDP applies specific thresholds for classifying organized violence."
    },
    {
      "title": "Far-Right Music Events, Protests, and Violence: A County-Level Dataset for Germany, 2013–2024",
      "url_or_doi": "https://pmc.ncbi.nlm.nih.gov/articles/PMC13538395/",
      "justification": "A research dataset compiling county-level information about far-right music events, protests, and violence in Germany between 2013 and 2024. It combines official government disclosures with information from victim-support organizations. The dataset is particularly relevant for analyzing the geographic distribution and development of right-wing extremism, political mobilization, and extremist violence during 2020–2024."
    },
    {
      "title": "BKA – Crime in the Context of Immigration and Refugee Migration, 2023",
      "url_or_doi": "https://www.karriere.bka.de/SharedDocs/Downloads/DE/Publikationen/JahresberichteUndLagebilder/KriminalitaetImKontextVonZuwanderung/KriminalitaetImKontextVonZuwanderung_2023.pdf?__blob=publicationFile&v=2",
      "justification": "Official German Federal Criminal Police Office statistics examining crime in the context of immigration and refugee migration. Includes information about offenses targeting asylum accommodation, politically motivated crimes related to immigration, and trends extending into the 2020s. Useful for investigating social conflict, refugee security, anti-immigrant extremism, and violence against migrant communities. The report contains statistical tables and historical comparisons rather than a standalone machine-readable dataset."
    },
    {
      "title": "German Federal Statistical Office – Annual Criminal Convictions by Offense Type",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/table/24311-0001/",
      "justification": "An official annual time-series dataset of criminal convictions in Germany, organized by offense category. It supports analysis of criminal justice trends during the 2020s, including homicide, bodily harm, robbery, and offenses against the state and public order. Particularly useful for studying long-term changes in security conditions and distinguishing trends in court convictions from police-recorded crime."
    },
    {
      "title": "OSCE ODIHR – Germany Hate Crime Report Data, 2024",
      "url_or_doi": "https://hatecrime.osce.org/reporting/germany/2024",
      "justification": "Provides Germany-specific official hate crime data and contextual information for 2024 as part of the OSCE's international reporting framework. Includes statistical information on hate crimes and their motivations, making it useful for studying identity-based violence, social polarization, minority security, and the institutional response to hate crime. The standardized reporting framework also supports comparisons with other European countries."
    },
    {
      "title": "German Federal Statistical Office – Criminal Prosecution and Justice Statistics",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Government/Justice/_node.html",
      "justification": "An official statistical portal covering Germany's criminal justice system, including prosecutions, convictions, and related judicial outcomes. It provides access to statistical series relevant to the 2020s. Researchers can use these data to investigate public security, the institutional response to violence, and the functioning of the criminal justice system. This is a dataset access portal rather than a single downloadable dataset."
    }
  ]
}
